	if (ready === "stop") {
		backToSales(serial, exec, ops);
		return "skip";
	}
	if (dry) {
		backToSales(serial, exec, ops);
		return ready === "skip" ? "skip" : "price";
	}
	if (ready === "skip") {
		backToSales(serial, exec, ops);
		return "skip";
	}
	if (stopRequested()) {
		backToSales(serial, exec, ops);
		return "stop";
	}
