		expect(proposals.filter((proposal) => proposal.skipReason === "cooldown")).toHaveLength(2);
	});

	test("쿨타임·15회 글도 내릴 가격이 있으면 가격만 내린다", () => {
		const coolingHigh = aimed({ id: "ch", title: "차", price: 300_000, hearts: 5, target: 295_000 });
		const coolingRow = { ...coolingHigh, nextBumpAt: "2026-10-29T01:00:00.000Z" };
