			bumpCount: MAX_BUMPS,
		};
		const proposals = planOf([coolingRow, fullHigh]);
		expect(proposals.map((proposal) => proposal.action)).toEqual(["price-only", "price-only"]);
		expect(proposals.map((proposal) => proposal.price)).toEqual([295_000, 49_000]);
