/**
 * 화면 트리 읽기. `uiautomator dump` 는 화면이 잠잠해질 때까지 기다려 한 번에 2초쯤 걸린다
 * (261105 회차: 덤프 208번이 652초 중 490초).
 * 폰 쪽 일은 droid 가 한다: `droid dump` 는 상주 NodeDump 서버(app_process, 앱 설치 없음)에 파일로 요청해
 * 덤프 한 번을 adb 왕복 하나로 끝내고, 서버가 안 되는 폰이면 uiautomator 로 돌아간다.
 * `NODE_DUMP=off` 는 droid 가 직접 읽어 uiautomator 만 쓴다(dev/droid/nodes.go).
 * droid 가 없는 경로(테스트의 adb 가짜)는 uiautomator 로만 읽는다.
 */
import { spawnSync } from "node:child_process";
import { droidOf } from "./droid";
import type { AdbExec } from "./phone";

const DUMP_FILE = "/sdcard/window_dump.xml";

/** droid 없이 도는 경로에서 상주 서버를 내리는 셸. droid 는 `rest --nodes` 가 같은 일을 한다. */
export const STOP_SCRIPT =
	"[ -f /data/local/tmp/droid-nodes/pid ] && kill $(cat /data/local/tmp/droid-nodes/pid) 2>/dev/null; rm -rf /data/local/tmp/droid-nodes";

/** 지금 화면의 XML. 빈 문자열이면 못 읽은 것이다(전환 중인 화면이거나 기기 문제). */
export function dumpScreen(serial: string, exec: AdbExec): string {
	const d = droidOf(exec);
	// exit 2 는 이번 한 번 화면이 비었다는 뜻이고 3 은 기기 문제다. 둘 다 이번 덤프만 빈 문자열이다.
	if (d) {
		const run = d(["dump", "--serial", serial]);
		return run.status === 0 ? run.stdout.trim() : "";
	}
	exec(["-s", serial, "shell", "uiautomator", "dump", DUMP_FILE]);
	return exec(["-s", serial, "shell", "cat", DUMP_FILE]).stdout;
}

/** 회차 끝에 서버를 내린다. 안 내려도 요청이 없으면 스스로 끝난다. */
export function stopNodeServer(serial: string, exec: AdbExec) {
	const d = droidOf(exec);
	if (d) {
		d(["rest", "--nodes", "--serial", serial]);
		return;
	}
	exec(["-s", serial, "shell", STOP_SCRIPT]);
}

/**
 * 스와이프 뒤 목록이 멈출 때까지 읽는다. NodeDump 는 0.2초면 읽어서, 관성으로 아직 움직이는 목록을 잡으면
 * 앞 창과 같은 창으로 보고 '더 안 내려감'으로 끝낸다(261105 21:02: 판매중 32건 중 18·21건).
 * uiautomator 는 잠잠해질 때까지 기다려서 이 문제가 없었다. 연속 두 덤프가 같으면 멈춘 것이다.
 */
export function settledDump(read: () => string, pause: (ms: number) => void = (ms) => void spawnSync("sleep", [(ms / 1000).toFixed(3)]), tries = 6): string {
	let prev = read();
	for (let i = 0; i < tries; i++) {
		pause(150);
		const next = read();
		if (next === prev) return next;
		prev = next;
	}
	return prev;
}

function drag(serial: string, exec: AdbExec, x: number, from: number, to: number) {
	const mid = Math.round((from + to) / 2);
	const steps = [
		`input motionevent DOWN ${x} ${from}`,
		`input motionevent MOVE ${x} ${mid}`,
		`input motionevent MOVE ${x} ${to}`,
		"sleep 0.25",
		`input motionevent UP ${x} ${to}`,
	].join(" && ");
	exec(["-s", serial, "shell", steps]);
	sleep(250);
}

function noteSkip(target: string, reason: string) {
	journal?.next({ cmd: "note", action: "건너뜀", reason, result: "화면을 움직이지 않음", target });
}

/** 한 단계의 시작·끝을 회차 시각으로 남긴다. 확정 전 중단은 이 단계 사이에서만 일어난다. */
function act(
	serial: string,
	record: { cmd: string; action: string; reason: string; target?: string; ok?: boolean },
	run: () => void,
	result: () => string,
	ok?: () => boolean,
) {
	const log = serial === journalSerial ? journal : null;
	const startMs = log?.now() ?? 0;
	run();
	const outcome = result();
	const endMs = log?.now() ?? 0;
	log?.next({ ...record, result: outcome, ...(ok ? { ok: ok() } : {}) }, { startMs, endMs });
}

/** 앞에 떠 있는 창(패키지/액티비티). 판매관리가 아닐 때 무엇이 가렸는지 로그에 남긴다. */
export function focusOf(serial: string, exec: AdbExec): string {
	const blob = exec(["-s", serial, "shell", "dumpsys", "window"]).stdout;
	return blob.match(/mCurrentFocus=Window\{\S+ \S+ ([^}\s]+)\}/)?.[1] ?? "모름";
}

function center(node: { x: number; y: number; w: number; h: number }) {
	return {
		x: Math.floor(node.x + node.w / 2),
		y: Math.floor(node.y + node.h / 2),
	};
}

function noConfirm(ops: ScreenOp[]): boolean {
	return ops.every((op) => op.kind !== "tap" || (op.label !== CONFIRM_BUMP && op.label !== CONFIRM_EDIT));
}

function fail(note: string, touched: boolean, ops: ScreenOp[] = []): PhoneRun {
	return {
		bumped: 0,
		pricedOnly: 0,
		skipped: 0,
		note,
		touched,
		confirmed: false,
		ops,
		stopped: false,
		logDir: journal?.dir,
	};
}

function stopped(bumped: number, pricedOnly: number, skipped: number, ops: ScreenOp[], byUser: boolean): PhoneRun {
	return {
		bumped,
		pricedOnly,
		skipped,
		note: byUser ? STOPPED_NOTE : "가격 칸이 승인값과 달라 확정하지 않았어요",
		touched: true,
		confirmed: false,
		ops,
		stopped: byUser,
		logDir: journal?.dir,
	};
}

